F2: add \`by_author()\` returning \`{author: count}\` over books.all_books().
F5: add \`as_json()\` returning a JSON string \`{"summary": summary(), "by_author": by_author()}\` (json.dumps, sort_keys=True).
Tests in a new tests/test_report.py (clear books in setup_function). Run \`python -m pytest\`. Do not commit.` },
  { key: 'F3', tickets: ['F3'], prompt: `fix:F3 (shelf/cli.py, shelf/__init__.py, tests/test_cli.py only)
F3: \`python -m shelf --version\` prints \`shelf 0.1.0\` and exits 0. Define \`__version__ = "0.1.0"\` in shelf/__init__.py and use argparse action="version". Test in a new tests/test_cli.py. Run \`python -m pytest\`. Do not commit.` },
  { key: 'F4', tickets: ['F4'], prompt: `fix:F4 (new shelf/export.py, new tests/test_export.py only)
F4: \`export_csv()\` returns CSV text of every book with a \`title,author\` header row, via the csv module (lineterminator="\\n"). Test in tests/test_export.py (clear books in setup_function). Run \`python -m pytest\`. Do not commit.` },
]
const SCHEMA = { type: 'object', properties: { passed: { type: 'boolean' }, why: { type: 'string' }, check: { type: 'string' } }, required: ['passed', 'why', 'check'] }
const results = await pipeline(
  ITEMS,
  it => agent(`Working directory: ${ROOT}\nOther agents are editing other files in parallel; touch only the files named.\n${it.prompt}`, { label: `AAAC fix:${it.key}`, phase: 'Fix' }).then(r => ({ it, r })),
  ({ it, r }) => agent(`Working directory: ${ROOT}\nverify:${it.key} - independently read the item's diff (git diff / git status for new files) and run \`python -m pytest\`; passed:true only if the ticket text is met and the run is green, with the check named. Do not edit files. Other items change other files in parallel; judge only yours.\nTicket task:\n${it.prompt}\n\nFixer report:\n${r}`, { label: `AAAC verify:${it.key}`, phase: 'Verify', schema: SCHEMA }).then(v => it.tickets.map(t => ({ ticket: t, ...v })))
)
return results.flat()

