cd C:/Users/Ikran/AppData/Local/Temp/claude/C--tools-Projects-skillator2/27d934bf-f525-478b-b318-9a3621680768/scratchpad/fx-chain-1 && cat > shelf/report.py <<'EOF'
"""One-line summary of the catalogue."""
import json

from shelf import books


def summary():
    return "%d books" % len(books.all_books())


def by_author():
    counts = {}
    for book in books.all_books():
        counts[book["author"]] = counts.get(book["author"], 0) + 1
    return counts


def as_json():
    return json.dumps({"summary": summary(), "by_author": by_author()}, sort_keys=True)
EOF
cat > tests/test_report.py <<'EOF'
import json

from shelf import books, report


def setup_function():
    books.clear()


def test_by_author_empty():
    assert report.by_author() == {}


def test_by_author_counts():
    books.add("Dune", "Frank Herbert")
    books.add("Children of Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert report.by_author() == {"Frank Herbert": 2, "Jane Austen": 1}


def test_as_json():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    out = report.as_json()
    assert json.loads(out) == {
        "summary": "2 books",
        "by_author": {"Frank Herbert": 1, "Jane Austen": 1},
    }
    assert out == json.dumps(json.loads(out), sort_keys=True)
    assert out.index('"by_author"') < out.index('"summary"')


def test_as_json_empty():
    assert json.loads(report.as_json()) == {"summary": "0 books", "by_author": {}}
EOF
